class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}          # key -> value
        self.order = {}         # key -> usage timestamp

    def _update_usage(self, key):
        self.order[key] = self._current_time()

    def _get_least_recent(self) -> str:
        # Key with the smallest timestamp
        return min(self.order.keys(), key=lambda k: self.order[k])

    def _current_time(self) -> int:
        # In practice you'd use time.time(), but using a simple counter works too.
        return len(self.order)  # length grows, so smallest index = earliest

    def get(self, key):
        if key not in self.cache:
            return -1
        self._update_usage(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self._update_usage(key)
            self.cache[key] = value
            return
        if len(self.cache) >= self.capacity:
            lru_key = self._get_least_recent()
            del self.cache[lru_key]
            del self.order[lru_key]
        self.cache[key] = value
        self._update_usage(key)
